"""


def solve(board: list[list[str]]) -> list[list[str]]:
    rows, cols = len(board), len(board[0])
    result = [row[:] for row in board]

    def mark(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or result[r][c] != 'O':
            return
        result[r][c] = 'S'
        mark(r + 1, c)
        mark(r - 1, c)
        mark(r, c + 1)
        mark(r, c - 1)

