    result = ''
    if (numerator < 0) != (denominator < 0):
        result += '-'
    num = abs(numerator)
    den = abs(denominator)
    result += str(num // den)
    remainder = num % den
    if remainder == 0:
        return result
    result += '.'
    seen = {}
    while remainder != 0:
        if remainder in seen:
            index = seen[remainder]
            return result[:index] + '(' + result[index:] + ')'
        seen[remainder] = len(result)
        remainder *= 10
        result += str(remainder // den)
        remainder %= den
    return result


