def solve(k: int, n: int) -> list[list[int]]:
    result = []

    def backtrack(start, remaining, current):
        if len(current) == k:
            if remaining == 0:
                result.append(current[:])
            return
        for value in range(start, 10):
            if value > remaining:
                break
            current.append(value)
            backtrack(value + 1, remaining - value, current)
            current.pop()

